def test_auto_width():
    config = Config()
    root = Node(config)
    root.flex_direction = FlexDirection.ROW
    root.position_type = PositionType.ABSOLUTE
    root.width = "auto"
    root.height = 50
    root_child0 = Node(config)
    root_child0.width = 50
    root_child0.height = 50
    root.insert_child(root_child0, 0)
    root_child1 = Node(config)
    root_child1.width = 50
    root_child1.height = 50
    root.insert_child(root_child1, 1)
    root_child2 = Node(config)
    root_child2.width = 50
    root_child2.height = 50
    root.insert_child(root_child2, 2)
    root.calculate_layout(None, None, Direction.LTR)
    assert root.layout.left == pytest.approx(0, abs=1e-4)
    assert root.layout.top == pytest.approx(0, abs=1e-4)
    assert root.layout.width == pytest.approx(150, abs=1e-4)
    assert root.layout.height == pytest.approx(50, abs=1e-4)
